import json
import csv
import re
import math
from xml.dom import minidom

# Load questions
with open('/Volumes/extern-1T-hardisk/workspace/01-repo/03-agents/Turbo-pi/packages/agent-server/eval/results/campaign-20260819/day1/experiment/task_00063_second_pass_quality_audit_of_question_169663/data/questions_batch_42.json', 'r') as f:
    questions = json.load(f)

# Load answer keys
def load_answer_key(filename):
    answer_key = {}
    with open(filename, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            answer_key[int(row['question_id'])] = {
                'option_letter': row['correct_answer'],
                'numeric_value': float(row['correct_value']) if row['correct_value'] else None,
                'last_updated': row['last_updated']
            }
    return answer_key

key_v1 = load_answer_key('/Volumes/extern-1T-hardisk/workspace/01-repo/03-agents/Turbo-pi/packages/agent-server/eval/results/campaign-20260819/day1/experiment/task_00063_second_pass_quality_audit_of_question_169663/data/answer_key_v1.csv')
key_v2 = load_answer_key('/Volumes/extern-1T-hardisk/workspace/01-repo/03-agents/Turbo-pi/packages/agent-server/eval/results/campaign-20260819/day1/experiment/task_00063_second_pass_quality_audit_of_question_169663/data/answer_key_v2.csv')
key_v3 = load_answer_key('/Volumes/extern-1T-hardisk/workspace/01-repo/03-agents/Turbo-pi/packages/agent-server/eval/results/campaign-20260819/day1/experiment/task_00063_second_pass_quality_audit_of_question_169663/data/answer_key_v3.csv')

# Background colors for hidden text detection
BACKGROUND_COLORS = ["white", "#ffffff", "#fff", "rgb(255,255,255)"]

def parse_svg_text(svg_content):
    """Extract all text elements from SVG"""
    texts = []
    # Find all text elements
    text_pattern = r'<text[^>]*>([^<]+)</text>'
    matches = re.findall(text_pattern, svg_content, re.DOTALL)
    for match in matches:
        texts.append(match.strip())
    return texts

def check_duplicate_options(question):
    """Check for duplicate option values"""
    options = question.get('options', [])
    values = []
    for opt in options:
        # Extract numeric value from option
        match = re.search(r'[-+]?\d+\.?\d*', opt.replace(',', ''))
        if match:
            values.append(float(match.group()))
        else:
            # For non-numeric options, use letter representation
            match = re.search(r'[A-D]', opt.replace('.', ''))
            if match:
                values.append(match.group())
            else:
                values.append(opt.replace(',', '').strip())

    # Check for duplicates
    duplicates = []
    seen = {}
    for val in values:
        if val in seen:
            duplicates.append((seen[val], val, options.index(val)))
        seen[val] = options.index(val)

    return duplicates

def parse_answer_key_value(option_letter, question):
    """Extract numeric value from an option"""
    opt_text = None
    for opt in question.get('options', []):
        if opt.startswith(option_letter + '.'):
            opt_text = opt
            break

    # Extract numeric value
    match = re.search(r'[-+]?\d+\.?\d*', opt_text.replace(',', '').replace(' cm', '').replace(' cm²', '').replace(' cm³', ''))
    if match:
        try:
            return float(match.group())
        except:
            return None
    return None

def check_answer_key_consistency(question_id):
    """Check if answer keys are consistent across versions"""
    issues = []
    q1 = key_v1.get(question_id)
    q2 = key_v2.get(question_id)
    q3 = key_v3.get(question_id)

    if q1 and q2 and q3:
        if q1['option_letter'] != q2['option_letter'] or q1['option_letter'] != q3['option_letter']:
            issues.append(f"All keys agree: {q1['option_letter']}")
            return issues

    issues = []
    if q1:
        issues.append(f"v1: {q1['option_letter']} ({q1['numeric_value']})")
    if q2:
        issues.append(f"v2: {q2['option_letter']} ({q2['numeric_value']})")
    if q3:
        issues.append(f"v3: {q3['option_letter']} ({q3['numeric_value']})")

    return issues

# Check questions for issues
for q in questions:
    qid = q['question_id']

    # Check for duplicate options
    duplicates = check_duplicate_options(q)
    if duplicates:
        print(f"\n=== Question {qid}: DUPLICATE OPTIONS ===")
        for dup in duplicates:
            print(f"  {dup[0]} and {dup[1]} are duplicates (index {dup[2]})")

    # Check answer key consistency
    key_issues = check_answer_key_consistency(qid)
    if key_issues:
        print(f"\n=== Question {qid}: KEY CONSISTENCY ISSUES ===")
        print(f"  {key_issues}")

    # Parse and check SVG
    if q.get('svg_file'):
        svg_path = f'/Volumes/extern-1T-hardisk/workspace/01-repo/03-agents/Turbo-pi/packages/agent-server/eval/results/campaign-20260819/day1/experiment/task_00063_second_pass_quality_audit_of_question_169663/svg/{q["svg_file"]}'
        with open(svg_path, 'r') as f:
            svg_content = f.read()

        texts = parse_svg_text(svg_content)
        print(f"\n=== Question {qid}: SVG TEXTS ===")
        for t in texts[:10]:  # Show first 10 texts
            print(f"  '{t}'")

        # Check for hidden text
        hidden_texts = []
        for t in texts:
            if t.lower() in [c.lower() for c in BACKGROUND_COLORS]:
                hidden_texts.append(t)
        if hidden_texts:
            print(f"\n  WARNING: Hidden text found: {hidden_texts}")

        # Check for answer leaks
        print(f"\n  Checking for answer leaks...")
        for option in q.get('options', []):
            match = re.search(r'[-+]?\d+\.?\d*', option.replace(',', ''))
            if match:
                opt_val = match.group()
                found_in_svg = any(opt_val in t or t.startswith(opt_val) for t in texts)
                if found_in_svg and opt_val:
                    print(f"    Option '{opt_val}' found in SVG: {[t for t in texts if opt_val in t]}")

print("\n\n=== ANSWER KEY SUMMARY FOR BATCH 42 ===")
for q in questions:
    qid = q['question_id']
    if qid in key_v1 or qid in key_v2 or qid in key_v3:
        v1_ans = key_v1.get(qid)
        v2_ans = key_v2.get(qid)
        v3_ans = key_v3.get(qid)

        print(f"\nQ {qid}:")
        print(f"  Question options: {q['options']}")
        print(f"  Labeled answer: {q['labeled_answer']}")

        vals = []
        if v1_ans:
            vals.append((v1_ans['option_letter'], v1_ans['numeric_value']))
        if v2_ans:
            vals.append((v2_ans['option_letter'], v2_ans['numeric_value']))
        if v3_ans:
            vals.append((v3_ans['option_letter'], v3_ans['numeric_value']))

        if vals:
            unique_vals = list(set([v[0] for v in vals]))
            print(f"  Keys show different answers: {unique_vals}")
ENDSCRIPT

